82: ### Authorization configuration and resource policy
83: 
84: ```ts
85: type Secret<T extends string> = { readonly value: T; toJSON(): "[REDACTED]" };
86: 
87: interface AuthConfig {
88:   readonly issuer: URL;
89:   readonly mcpResource: URL;
90:   readonly commonCalInteractionBase: URL;
91:   readonly publicBind: string;
92:   readonly privateBind: string;
93:   readonly databaseUrl: Secret<string>;
94:   readonly cookieKeys: readonly Secret<string>[];
95:   readonly jwks: Secret<string>;
96:   readonly bridgeKey: Secret<string>;
97:   readonly accessTokenTtlSeconds: number;
98:   readonly refreshTokenTtlSeconds: number;
99:   readonly handoffTtlSeconds: number;
100:   readonly allowedRedirectShapes: readonly RedirectShape[];
101: }
102: 
103: type RedirectShape =
104:   | { readonly kind: "loopback"; readonly host: "127.0.0.1" | "[::1]"; readonly port: "any" | number; readonly path: string }
105:   | { readonly kind: "custom-scheme"; readonly scheme: string; readonly path: string }
106:   | { readonly kind: "exact-https"; readonly uri: URL };
107: 
108: function loadConfig(environment: NodeJS.ProcessEnv): AuthConfig;
109: function validateResourceIndicator(resource: string | undefined, expected: URL): URL;
