146: ### Cross-host interaction handoff
147: 
148: ```ts
149: type HandoffToken = string & { readonly __handoff: unique symbol };
150: type ProviderInteractionUid = string & { readonly __interaction: unique symbol };
151: 
152: interface SanitizedInteraction {
153:   readonly clientId: string;
154:   readonly clientName: string;
155:   readonly redirectUri: URL;
156:   readonly resource: URL;
157:   readonly requestedScopes: readonly string[];
158:   readonly prompt: readonly ("login" | "consent")[];
159:   readonly expiresAt: Date;
160: }
161: 
162: type InteractionDecision =
163:   | { readonly kind: "login"; readonly subject: string; readonly authenticationMethods: readonly string[] }
164:   | { readonly kind: "consent"; readonly subject: string; readonly grantedScopes: readonly string[]; readonly resource: URL }
165:   | { readonly kind: "deny"; readonly error: "access_denied"; readonly description: string };
166: 
167: interface HandoffStore {
168:   create(uid: ProviderInteractionUid, view: SanitizedInteraction, ttlSeconds: number): Promise<HandoffToken>;
169:   lookup(token: HandoffToken): Promise<SanitizedInteraction | undefined>;
170:   decide(token: HandoffToken, decision: InteractionDecision): Promise<URL>;
171:   consumeForResume(token: HandoffToken, uid: ProviderInteractionUid): Promise<InteractionDecision>;
172: }
173: 
174: function bootstrapInteraction(req: Request, res: Response): Promise<void>;
175: function resumeInteraction(req: Request, res: Response): Promise<void>;
176: function getInternalInteraction(token: HandoffToken, authorization: string): Promise<SanitizedInteraction>;
177: function putInternalDecision(token: HandoffToken, authorization: string, decision: InteractionDecision): Promise<{ resumeUrl: URL }>;
178: ```
179: 
180: The browser first reaches the auth host so the provider can read its cookie. The service creates a hashed handoff and redirects to CommonCal. CommonCal reads/decides privately, then redirects the browser to the public resume URL. Only there does the service consume the handoff, re-read provider state, and finish the interaction. Provider cookies/payloads and bridge credentials never enter browser-visible state.
